flight_plan.header:
#include "autopilot.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
/* Quoted, not angle-bracketed: this header text sits inside the flight
   plan XML, and gen_aircraft does not re-escape it on output, so an angle
   bracket here corrupts the generated per-aircraft flight_plan.xml (the
   same round-trip problem the abi_event comment above describes). Quotes
   resolve to the system header just the same. */
#include "stdio.h"
#include "modules/datalink/datalink.h"
#include "modules/nav/nav_mission4_geofence.h"
#include "modules/relative_localization_filter/relative_localization_filter.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
#include "modules/core/abi.h"

/* Real AGL for the drop-release gate below, not GPS/baro-derived
   altitude: GetPosAlt()/GetAltRef() is precise in simulation (NPS gives
   perfect ground truth) but on real hardware that combination is nowhere
   near accurate enough to reliably trigger a release in a 0.5 m-wide
   window right above the ground - a real sub-2 m drop genuinely needs
   the rangefinder (sonar_i2c, airframe file) actually feeding this,
   which is exactly what USE_SONAR_I2C_AGL=TRUE (also set in the
   airframe) turns on: sonar_i2c.c broadcasts an AGL Abi message whenever
   it gets a valid, in-range, rotation-compensated reading. Subscribing
   here directly (mission4_agl_sonar_init(), called once from Start
   Mission4 below) rather than relying on some existing INS module to
   consume it and expose it through the normal state interface: this
   airframe's own ins_alt_float.c (the INS module Cherry-family airframes
   actually use) has no AGL Abi subscriber at all, confirmed by reading
   it - the message would otherwise just be broadcast and ignored.
   mission4_sonar_agl_time (autopilot.flight_time at the last valid
   reading) exists so the release gate below can tell a genuinely fresh
   sonar reading from a stale one (e.g. still up at search_height, far
   outside the sensor's real range - sonar_i2c.c only broadcasts once a
   reading is in-range and positive, so no update at all simply means no
   real ground return yet, same as it would on real hardware). */
static float mission4_sonar_agl = -1.0f;
static float mission4_sonar_agl_time = -1000.0f;
/* 1-element array, not a plain struct: avoids ever needing the address-
   of operator on this variable below. A bare use of that operator in
   real header code (not a comment) corrupts the per-aircraft generated
   flight_plan.xml the same way angle brackets do elsewhere in this file
   (confirmed the same way: gen_aircraft's writer doesn't re-escape
   header text on output, so even a correctly-escaped entity in the
   source round-trips back out unescaped and breaks re-parsing
   downstream) - avoiding the character entirely, not escaping it, is
   the only fix confirmed to actually survive the round trip. An array
   name decays to a pointer to its first element on its own, so passing
   the array directly below is identical in practice to taking this
   variable's address, without ever writing that operator. */
static abi_event mission4_agl_ev[1];

static void mission4_agl_cb(uint8_t sender_id __attribute__((unused)),
                             uint32_t stamp __attribute__((unused)),
                             float distance)
{
  mission4_sonar_agl = distance;
  mission4_sonar_agl_time = autopilot.flight_time;
}

static inline void mission4_agl_sonar_init(void)
{
  AbiBindMsgAGL(AGL_RANGEFINDER_I2C_ID, mission4_agl_ev, mission4_agl_cb);
}

/* rangefinder_i2c is only loaded on the ap target; skip its report in NPS. */
static inline void mission4_rangefinder_report_start(void)
{
#ifdef RANGEFINDER_I2C_ADDR
  rangefinder_i2c_rangefinder_i2c_report_status = MODULES_START;
#endif
}

/* Fresh sonar AGL, or GetPosAlt()-GetAltRef() as a fallback: used by the
   release gate below so the mission still works (on GPS/baro alone,
   simulation-accurate but not realistic) even before the sonar has ever
   reported - e.g. mid-search, or if a real sensor drops out. 0.5 s
   freshness window is generous relative to SONAR_I2C_PERIODIC_FREQUENCY
   (100 Hz, airframe file) - only meant to catch "never reported yet" or
   "stopped reporting", not to be a tight filter. */
static inline float mission4_agl(void)
{
  if (!signbit(autopilot.flight_time - mission4_sonar_agl_time - 0.5f)) {
    return GetPosAlt() - GetAltRef();
  }
  return mission4_sonar_agl;
}

/* Shortest usable run-in: place DROP_APPROACH on the bearing from the
   source BACK TOWARD the aircraft, at whatever distance the aircraft
   already is, clamped to a workable range.

   It used to be planted 150 m due EAST of DROP_POINT unconditionally. With
   the source able to be anywhere that is an arbitrary direction: the
   aircraft finishes the search somewhere on the pattern and then has to fly
   out to an approach point that may be on the far side, adding transit and
   forcing the spiral to shed everything the transit could have shed on the
   way. Measured: 25 s and 0.88 of a revolution spiralling off 23 m, on top
   of a 150 m run-in the aircraft was not lined up for.

   Aiming the approach at the aircraft makes the transit, the descent and
   the final glide one straight line - it flies in descending and keeps
   going through the release with no turn.

   Clamped below at MISSION4_APPR_MIN for TURN SETTLING, not for the glide
   slope. The aircraft arrives from the search on an arbitrary heading and
   has to turn onto the approach line: at 12.5 m/s the turn radius is 16 m
   at this airframe's 45 deg ROLL_MAX_SETPOINT and about 28 m at a more
   typical 30 deg, so a reversal costs 50-87 m of travel before it is even
   pointing the right way, plus a few seconds to settle. Measured with a
   58 m approach: still 4.8 deg off the bearing to the source AT RELEASE,
   throwing the payload 1.7 m sideways - larger than every other error
   combined, and larger than the ballistics this whole gate computes.
   130 m leaves ~120 m of straight, settled run-in after the turn.
   Clamped above at MISSION4_APPR_MAX so a search ending far out does not
   produce an enormous run-in. Between those the approach starts wherever
   the aircraft already is. */
#define MISSION4_APPR_MIN 130.0f
#define MISSION4_APPR_MAX 200.0f
/* Shortest run-in still worth flying: below this the aircraft cannot settle
   after the turn onto the approach and the angular error at release starts
   to dominate (measured 4.8 deg, 1.7 m sideways, on a 58 m approach). */
#define MISSION4_APPR_FLOOR 60.0f

/* True if the whole approach line - not just its far end - stays inside
   the geofence. The aircraft flies every metre between DROP_APPROACH and
   the source, so testing only the endpoint lets the middle of the run-in
   cross the boundary. */
static inline bool mission4_appr_line_ok(float sx, float sy, float ux, float uy, float ad)
{
  int k;
  for (k = 0; k != 5; k++) {
    float f = 0.25f * (float)k;
    if (!mission4_in_valkenburg_safe(sx + ux * ad * f, sy + uy * ad * f)) { return FALSE; }
  }
  return TRUE;
}

static inline void mission4_place_approach(uint8_t drop_wp, uint8_t appr_wp)
{
  float sx = waypoints[drop_wp].x, sy = waypoints[drop_wp].y;
  float dx = GetPosX() - sx, dy = GetPosY() - sy;
  float d = sqrtf(dx * dx + dy * dy);
  if (signbit(d - 1.0f)) { dx = 0.0f; dy = 1.0f; d = 1.0f; }

  /* Preferred bearing is DUE EAST, reproducing the original fixed
     "150 m east of DROP_POINT" placement, which worked: east stays inside
     the FZ1-FZ6 polygon from anywhere in the search area, so the aircraft
     flies out east, turns, and runs back in westward.
     An earlier version preferred the bearing back toward the aircraft, on
     the reasoning that it needs less turning. That was wrong here: from a
     source near the northern edge it points north or west, 73-83 m outside
     the polygon, so the geofence exception fired mid-approach and derouted
     to Standby before the release every time.
     The scan below still exists so the approach adapts if east is ever
     blocked - a source in a different part of the zone, or nearer the
     eastern wall - but east is tried first and will normally win, so the
     behaviour matches the original by default. */
  float base = 3.14159265f / 2.0f;   /* due east */
  (void)dx; (void)dy;
  float want = d;
  if (signbit(want - MISSION4_APPR_MIN)) { want = MISSION4_APPR_MIN; }
  if (!signbit(want - MISSION4_APPR_MAX)) { want = MISSION4_APPR_MAX; }

  float ad = want;
  int guard = 0;
  while (guard != 12) {
    int i;
    for (i = 0; i != 37; i++) {
      int half = (i + 1) / 2;
      float sgn = ((i % 2) == 0) ? 1.0f : -1.0f;
      float b = base + sgn * (float)half * (10.0f * 3.14159265f / 180.0f);
      float ux = sinf(b), uy = cosf(b);
      if (mission4_appr_line_ok(sx, sy, ux, uy, ad)) {
        waypoints[appr_wp].x = sx + ux * ad;
        waypoints[appr_wp].y = sy + uy * ad;
        return;
      }
    }
    ad -= 10.0f;
    if (signbit(ad - MISSION4_APPR_FLOOR)) { break; }
    guard++;
  }
  /* No bearing at any length keeps the line inside - the source must be
     hard against the boundary. Fall back to the shortest run-in toward the
     aircraft and let the geofence exception handle it. */
  waypoints[appr_wp].x = sx + (dx / d) * MISSION4_APPR_FLOOR;
  waypoints[appr_wp].y = sy + (dy / d) * MISSION4_APPR_FLOOR;
}

/* Distance ahead of DROP_POINT at which the release must be COMMANDED so
   the payload lands on it, rather than a fixed 15 m guess:

     lead = v * (TRIGGER_DELAY + sqrt(2h/g))

   The first term is the mechanism's own latency - the aircraft keeps
   flying between the command and the payload actually leaving - and the
   second is the ballistic throw during the fall. Measured on a real drop:
   released 13.3 m short of the true source at 1.26 m AGL and 12 m/s, where
   the lead needed was 18.1 m, so the payload would have landed 4.8 m past
   the target. The fixed 15 m gate happened to be close at one particular
   speed and height and drifts as either changes.

   Note the split: at 12 m/s the trigger delay contributes 12.0 m of that
   18.1 m and the fall only 6.1 m. TRIGGER_DELAY is still a TODO guess in
   the airframe file, so it is by far the dominant uncertainty - at 0.5 s
   the lead is 12.1 m, at 1.5 s it is 24.1 m. Computing it here does not
   make the drop accurate on its own; it makes TRIGGER_DELAY the single
   number to calibrate on real hardware instead of a hidden bias inside a
   magic constant.

   Height comes from mission4_agl (the rangefinder), clamped non-negative
   so a bad reading cannot produce a NaN in the sqrt. */
/* True only while the aircraft is CLOSING on the target. The release gate
   compares a squared distance against the squared lead, which is unsigned -
   it would fire just as readily five metres PAST the target as five metres
   before, throwing the payload that much further beyond. It has not
   happened yet only because the altitude window has always opened on the
   inbound leg; if the descent ever lagged, the first moment both conditions
   were true could be on the far side. Comparing the current squared range
   with the previous tick's is enough to tell the two apart. */
static float mission4_prev_d2 = 1.0e9f;

static inline bool mission4_closing(uint8_t drop_wp)
{
  float dx = GetPosX() - waypoints[drop_wp].x;
  float dy = GetPosY() - waypoints[drop_wp].y;
  float d2 = dx * dx + dy * dy;
  bool closing = signbit(d2 - mission4_prev_d2);
  mission4_prev_d2 = d2;
  return closing;
}

static inline float mission4_release_lead(void)
{
  float _v = stateGetHorizontalSpeedNorm_f();
  /* Sink rate, positive downward. The aircraft is still descending on the
     final glide (measured -0.63 m/s at release), and that matters twice. */
  /* [0].z, not an arrow: a raw angle bracket in this header survives into
     the generated per-aircraft flight_plan.xml unescaped and breaks its
     re-parse (same trap as the stdio include and the signbit comparisons
     above). Indexing the returned pointer reads the same field. */
  float _w = -(stateGetSpeedEnu_f()[0].z);
  if (signbit(_w)) { _w = 0.f; }   /* climbing: no help from sink, ignore */

  /* 1. The payload leaves TRIGGER_DELAY AFTER the command, by which time
        the aircraft has sunk _w*TRIGGER_DELAY further. Using the height at
        the command instant overestimates the drop height, and so the fall
        time and the throw. */
  float _h = mission4_agl() - _w * TRIGGER_DELAY;
  if (signbit(_h)) { _h = 0.f; }

  /* 2. It also inherits the aircraft's downward velocity, so it is not a
        free fall from rest: h = w*t + g*t^2/2, solved for t. */
  float _t = (-_w + sqrtf(_w * _w + 2.f * 9.81f * _h)) / 9.81f;

  /* Drag acts on AIRSPEED, not ground speed: the payload is decelerated
     toward the air mass, so a tailwind reduces the drag it feels and a
     headwind increases it. Project wind onto the ground track and use the
     relative speed for drag, keeping ground speed for the throw. Wind is
     zero in NPS so this cannot be validated here, but it is the largest
     uncorrected real-world term after the acoustic estimate. */
  float _dir = stateGetHorizontalSpeedDir_f();
  float _wn = stateGetHorizontalWindspeed_f()[0].x;
  float _we = stateGetHorizontalWindspeed_f()[0].y;
  float _walong = _we * sinf(_dir) + _wn * cosf(_dir);
  float _vrel = _v - _walong;

  /* First-order drag on the throw: decelerates at (ALPHA/MASS)*vrel^2, so
     the payload travels less far than the ballistic v*t and lands SHORT of
     a no-drag prediction - about 0.4 m for the real 250 g package in still
     air at 12 m/s. Clamped so a bad ALPHA/MASS cannot invert the throw. */
  float _throw = _v * _t;
  float _drag = 0.5f * ((float)ALPHA / (float)MASS) * _vrel * _vrel * _t * _t;
  if (!signbit(_drag - _throw)) { _drag = 0.f; }

  /* Half a nav tick of travel, removing the gate's quantisation BIAS: the
     exception is evaluated once per NAVIGATION_FREQUENCY tick and fires on
     the first one already inside the lead, so on average the aircraft is
     half a tick past the ideal point - 0.3 m at 12 m/s and 20 Hz, always
     the same direction, so the payload consistently lands long. */
  float _tick = _v / (2.0f * (float)NAVIGATION_FREQUENCY);

  return _v * TRIGGER_DELAY + (_throw - _drag) + _tick;
}

#ifdef SITL
/* Numerically integrate where the payload ACTUALLY lands, rather than
   predicting it from the closed-form lead. Test scaffolding only - it never
   compiles on the aircraft.

   This matters because MISS, the IMPACT marker and the release gate itself
   all come from one formula: lead = v*(TRIGGER_DELAY + fall) with a
   first-order drag term. If that formula is wrong, every one of those
   numbers is wrong in the same direction and still looks small and
   plausible. Integrating the trajectory separately - Euler steps, drag
   acting on the air-relative velocity, gravity, real wind - gives a second
   opinion that shares none of the closed form's approximations: no
   linearised drag, no assumed constant sink, no small-angle anything.
   Agreement between them is evidence the formula holds; a gap is the size
   of its error.

   It still cannot validate the PHYSICS - TRIGGER_DELAY, ALPHA and MASS are
   estimates, and this integration trusts them exactly as the formula does.
   Only a real drop test closes that loop. What this catches is mistakes in
   the maths, which is a different and more tractable class of error. */
static inline void mission4_sim_payload(uint8_t impact_wp)
{
  float dir = stateGetHorizontalSpeedDir_f();
  float v = stateGetHorizontalSpeedNorm_f();
  float x = GetPosX(), y = GetPosY(), z = mission4_agl();
  float vx = v * sinf(dir), vy = v * cosf(dir);
  float vz = stateGetSpeedEnu_f()[0].z;            /* positive up */
  float we = stateGetHorizontalWindspeed_f()[0].y; /* east  */
  float wn = stateGetHorizontalWindspeed_f()[0].x; /* north */
  float am = (float)ALPHA / (float)MASS;
  float dt = 0.005f;
  int k;

  /* Still bolted to the aircraft for TRIGGER_DELAY: it simply goes wherever
     the aircraft goes, so continue on the current velocity. */
  int n = (int)(TRIGGER_DELAY / dt);
  for (k = 0; k != n; k++) { x += vx * dt; y += vy * dt; z += vz * dt; }

  /* Free flight: drag decelerates it toward the air mass, gravity pulls it
     down, stop at ground contact. */
  for (k = 0; k != 4000; k++) {
    if (signbit(z)) { break; }
    float rx = vx - we, ry = vy - wn, rz = vz;
    float sp = sqrtf(rx * rx + ry * ry + rz * rz);
    float b = am * sp;
    vx -= rx * b * dt;
    vy -= ry * b * dt;
    vz -= rz * b * dt + 9.81f * dt;
    x += vx * dt; y += vy * dt; z += vz * dt;
  }
  waypoints[impact_wp].x = x;
  waypoints[impact_wp].y = y;
}
#endif

/* Record the release conditions at the instant the gate fires. The drop
   is over in about a second - measured 1.0 s below 1.5 m AGL, with the
   climb-out crossing 2 m and 3 m only 0.2 s apart - so a GCS strip
   updating at a few Hz can easily show 2 m on the way down and 3 m on the
   way up while never displaying the actual release height. Sent as an
   INFO_MSG so it lands in the GCS console AND in var/logs, and printed to
   stdout under SITL where the sim console is right there.
   Both altitude sources are reported: mission4_agl() is what the gate
   actually decided on (the rangefinder, or GPS/baro if the sonar has gone
   stale - see mission4_agl above), while GetPosAlt()-GetAltRef() is what
   the GCS strip shows. They agreed within 6 cm in simulation, but they are
   different sensors and on real hardware they will not. */
static inline void mission4_log_release(uint8_t drop_wp, uint8_t true_wp, uint8_t impact_wp)
{
  char _m4msg[128];
  float _agl_gate = mission4_agl();
  float _agl_baro = GetPosAlt() - GetAltRef();
  float _spd = stateGetHorizontalSpeedNorm_f();
  float _lead = mission4_release_lead();
  float _px = GetPosX(), _py = GetPosY();
  /* Distance to the ESTIMATE the gate actually aimed at - the only one of
     these available on a real flight. */
  float _ex = _px - waypoints[drop_wp].x, _ey = _py - waypoints[drop_wp].y;
  float _d_est = sqrtf(_ex * _ex + _ey * _ey);
  /* Distance to the hidden true source, and the predicted impact error:
     project the release point forward by the computed lead along the
     current ground track (where the payload is actually going) and measure
     from there. Test scaffolding only - true_wp is the simulator's ground
     truth, the same one mission4_sample_signal reads to synthesise SPL, and
     neither exists on a real flight. */
  float _tx = _px - waypoints[true_wp].x, _ty = _py - waypoints[true_wp].y;
  float _d_true = sqrtf(_tx * _tx + _ty * _ty);
  float _dir = stateGetHorizontalSpeedDir_f();
  float _ix = _px + _lead * sinf(_dir), _iy = _py + _lead * cosf(_dir);
  float _mx = _ix - waypoints[true_wp].x, _my = _iy - waypoints[true_wp].y;
  float _miss = sqrtf(_mx * _mx + _my * _my);
  /* Stamp the predicted landing point so the GCS shows it. Same projection
     the MISS figure uses: release point advanced by the computed lead along
     the current ground track. */
  waypoints[impact_wp].x = _ix;
  waypoints[impact_wp].y = _iy;
  waypoints[impact_wp].a = waypoints[true_wp].a;
  float _sim = -1.0f;
#ifdef SITL
  /* Overwrite the marker with the integrated result - it is the better
     estimate - and keep the closed-form MISS alongside so the two can be
     compared. */
  mission4_sim_payload(impact_wp);
  float _sx = waypoints[impact_wp].x - waypoints[true_wp].x;
  float _sy = waypoints[impact_wp].y - waypoints[true_wp].y;
  _sim = sqrtf(_sx * _sx + _sy * _sy);
#endif
  int _n = snprintf(_m4msg, sizeof(_m4msg),
                    "DROP agl=%.2f spd=%.1f lead=%.1f dTrue=%.1f MISS=%.2f SIM=%.2f",
                    _agl_gate, _spd, _lead, _d_true, _miss, _sim);
  /* signbit, not a comparison operator: a raw angle bracket in this header
     corrupts the generated flight_plan.xml on round-trip (see the include
     note above and the abi_event comment). Same idiom mission4_agl uses. */
  if (!signbit((float)_n)) {
    DOWNLINK_SEND_INFO_MSG(DefaultChannel, DefaultDevice, (uint8_t)_n, _m4msg);
  }
#ifdef SITL
  printf("[MISSION4] release: AGL %.2f m (sonar) / %.2f m (baro), %.1f m/s, lead %.1f m\n"
         "           %.1f m from estimate, %.1f m from TRUE source\n"
         "           predicted MISS %.2f m, integrated payload lands %.2f m from source\n",
         _agl_gate, _agl_baro, _spd, _lead, _d_est, _d_true, _miss, _sim);
  fflush(stdout);
#endif
}

/* Drop mechanism placeholder — no-op until the real release hardware exists,
   same pattern as IMAV2022_drop.xml (this repo's other drop-mission flight
   plan): redefine SwitchServoOn/Off (or DropOpen/DropClose directly) once
   the actual servo/mechanism is known, nothing else in this file needs to
   change. */
#ifndef SwitchServoOn
#define SwitchServoOn(_x) {}
#endif
#ifndef SwitchServoOff
#define SwitchServoOff(_x) {}
#endif
#define DropOpen SwitchServoOff
#define DropClose SwitchServoOn

/* Squared 2D distance (ignores altitude) from the aircraft to waypoint `wp`.
   Used by the Drop Mission4 Final exception to gate DropOpen() on actually
   being near DROP_POINT, not just on altitude — a circle around DROP_POINT
   (Drop Mission4 above) stays radius() away from it the whole time, so
   altitude alone isn't enough to confirm the aircraft is over the target.
   No comparison operator here on purpose: gen_aircraft's flight-plan writer
   does not re-escape header text on output, so a literal or escaped angle
   bracket in a header function corrupts the per-aircraft generated
   flight_plan.xml downstream (confirmed: xmllint fails on the regenerated
   file). The threshold check
   itself lives in the exception's cond= attribute using @LT instead, which
   is the paparazzi-native placeholder for this exact reason. */
static inline float mission4_dist2_to_wp(uint8_t wp) {
  float dx = GetPosX() - waypoints[wp].x;
  float dy = GetPosY() - waypoints[wp].y;
  return dx * dx + dy * dy;
}

/* PLACEHOLDER sound-source localization: simulates a flying-microphone
   sound-pressure-level (SPL) reading as a function of 3D distance
   (including the aircraft's own altitude, not just horizontal offset)
   to a hidden test source (TRUE_SOUND_SOURCE, waypoints section below,
   assumed to sit near ground level, matching a mannequin/beeper on the
   ground) — swap only this one decay computation for a real sensor read
   once hardware exists; everything else (sampling, best-point tracking,
   the search below) stays the same. Uses the real Motion
   Scout KTR alarm's own spec (95 dB at 3 m) with the standard inverse-
   square free-field spreading law, not an arbitrary placeholder curve —
   see mission4_sample_signal() below for how that calibration is used.
   Records every sample into a fixed-size array (position + SPL, matching
   "position X,Y,Z ... with sound pressure level measured at that
   location") and separately tracks the single best sample seen across
   the WHOLE search — not reset between phases — since the true peak
   could occur in any pass, not necessarily whichever runs last.
   "Best" is NOT simply "highest recorded SPL": this mission descends
   from ~70 m down to ~2 m AGL over the course of the search (idle-
   throttle glide, quieter than powered circling — see search_height's
   own comment), so raw SPL readings taken at very different altitudes
   aren't a fair comparison — a high-altitude sample "spends" most of
   its distance budget on altitude, not horizontal offset, and would
   lose to a low-altitude sample even if it was actually closer
   horizontally. mission4_sample_signal() below instead inverts each
   SPL reading into an implied slant range (via the same 95 dB/3 m
   model) and subtracts out the aircraft's own altitude — known
   precisely from GPS/baro, unlike the acoustic model — to isolate the
   horizontal component, and tracks whichever sample implies the
   SMALLEST horizontal range as "best". This is a narrower, more
   defensible use of the calibration than trying to pinpoint an exact
   2D fix by full multilateration (discussed and reverted earlier): it
   only separates a known quantity (own altitude) from an estimated one
   (slant range), not two unknowns from one reading.
   Throttled to 20 Hz (MISSION4_SAMPLE_PERIOD) — matching this
   airframe's own NAVIGATION_FREQUENCY (airframe file, 20 Hz) exactly,
   not just "fast": since the acoustic model (below) is an exact
   noiseless formula — no sensor noise term at all — the ONLY thing
   limiting how close mission4_best_x/y can land to the true source is
   how finely the flight path itself gets sampled, and the flight plan's
   own exceptions (this function is called from one) are only ever
   evaluated once per nav tick regardless of how low this period is set
   — 20 Hz is the actual ceiling, not an arbitrary choice; anything
   faster would just re-sample the same tick and buy nothing. At
   GLIDE_AIRSPEED (10 m/s) that's a sample every ~0.5 m along the track,
   as tight as this airframe's own nav loop can resolve. 600 samples
   comfortably covers a full Phase 1 lap plus the Phase 2 chord
   (confirmed via telemetry: sampling is active for ~28 s total across
   both) with room to spare. */
#define MISSION4_MAX_SAMPLES 600
#define MISSION4_SAMPLE_PERIOD 0.05f
#define MISSION4_KTR_REF_SPL 95.0f   /* Motion Scout KTR: 95 dB at 3 m */
#define MISSION4_KTR_REF_DIST 3.0f

static float mission4_sample_x[MISSION4_MAX_SAMPLES];
static float mission4_sample_y[MISSION4_MAX_SAMPLES];
static float mission4_sample_spl[MISSION4_MAX_SAMPLES];
/* Altitude at each sample. The SPL calibration gives a SLANT range; the
   solver needs the horizontal leg, so it has to know how high the aircraft
   was for each reading. Previously only x/y/spl were kept, which is why the
   samples could not be solved even in principle. */
static float mission4_sample_z[MISSION4_MAX_SAMPLES];
/* uint16_t, not uint8_t: MISSION4_MAX_SAMPLES is 600, so a uint8_t counter
   wrapped at 255 and the bounds check below (count - MAX, always negative)
   could never stop it - samples 256+ silently overwrote slots 0..255 and
   the array never held more than a partial, cyclically-corrupted set. */
static uint16_t mission4_sample_count = 0;
static float mission4_last_sample_time = -1000.0f;
static float mission4_best_horiz = 1.0e6f;
static float mission4_best_x = 0.0f;
static float mission4_best_y = 0.0f;
/* Fixed entry point for Search Mission4 Phase2's diameter chord below —
   captured once at the start of the block from mission4_best_x/y at that
   point, not re-read afterward, so further sampling during the chord
   itself (which keeps updating mission4_best_x/y) can't shift the
   chord's own endpoints out from under it mid-flight. */
static float mission4_diameter_start_x = 0.0f;
static float mission4_diameter_start_y = 0.0f;

/* Real-time "peak passed" detection for Phase2's diameter chord: rather
   than flying the whole chord and only deciding afterward by looking
   back at every recorded sample, watch the TREND as readings come in.
   mission4_worse_streak counts consecutive samples that were no better
   than the one right before them (not the best-ever — the immediately
   preceding one, so this tracks direction of travel, not overall best).
   Once that streak reaches MISSION4_PEAK_CONFIRM_COUNT, it means the
   aircraft was closing in on the source and has now been moving away
   from it for a few readings in a row — the peak was just passed, so
   the search can commit and turn back toward it (mission4_best_x/y
   already holds that position) instead of continuing on toward the
   chord's far end. The streak requirement (not "any single worse
   reading") exists purely to reject a noisy blip — this simulation has
   none, but a real sensor will, and this logic needs to still work with
   one.
   mission4_phase2_samples/MISSION4_PEAK_MIN_SAMPLES guard against a
   different failure than the streak alone can catch: confirmed via
   telemetry that the streak reached MISSION4_PEAK_CONFIRM_COUNT within
   about a second of entering Phase 2, cutting the chord off almost
   immediately — not because of stale state carried over from phase 1
   (that's a separate, already-fixed bug; verified this one is genuine
   phase-2 data), but because the aircraft is still curving onto the
   chord's own line right at the start (the same settling transient
   measured on the drop approach elsewhere in this file — several
   metres of cross-track error for the first stretch of any new straight
   leg, here reading as "getting worse" before the aircraft has actually
   gotten established on the line at all). Requiring a minimum sample
   count before the streak check is even consulted gives that transient
   time to clear before trusting the trend.
   Both constants below are sample COUNTS, not durations — scaled up
   10x total (3 to 30, 6 to 60) alongside MISSION4_SAMPLE_PERIOD's own
   10x rate increase (0.5s to 0.05s, above) so the physical time windows
   they were originally tuned against (1.5 s confirm, 3 s settle) stay
   the same; leaving them as sample counts after that change would have
   silently shrunk both windows by 10x and made the peak-passed trigger
   far noisier/earlier than it was ever tuned for. */
#define MISSION4_PEAK_CONFIRM_COUNT 30   /* ~1.5 s at MISSION4_SAMPLE_PERIOD */
#define MISSION4_PEAK_MIN_SAMPLES 60   /* ~3 s at MISSION4_SAMPLE_PERIOD */

static float mission4_prev_horiz = 1.0e6f;
static uint8_t mission4_worse_streak = 0;
static uint8_t mission4_phase2_samples = 0;

/* Least-squares multilateration over every sample collected during the
   search, replacing "DROP_POINT = wherever the aircraft was when the signal
   peaked".

   That previous rule could never be better than how close the flight path
   happened to pass: it reports an aircraft position, not a source position.
   Measured 2.3 m from the true source on a real run - already outside the
   2 m delivery requirement before the drop itself contributes any error,
   and not improvable by any amount of drop-geometry tuning.

   Each sample inverts the same SPL calibration used elsewhere into a slant
   range, then removes the (precisely known) altitude to get a horizontal
   range h_i from an aircraft position (x_i, y_i):

       (x_i - X)^2 + (y_i - Y)^2 = h_i^2

   Expanded, with S = X^2 + Y^2 held as a third unknown, that is LINEAR:

       2*x_i*X + 2*y_i*Y - S = x_i^2 + y_i^2 - h_i^2

   so the whole set solves as one 3x3 normal-equation system rather than
   needing an iterative fit. Every sample contributes, from positions all
   around the pattern, so the result is a genuine intersection of ranges
   instead of one lucky closest approach.

   Accumulated in double: coordinates are local metres, so x^2 terms reach
   1e5 and the normal equations square that again - float would lose most
   of the precision the extra samples are supposed to buy.

   No angle-bracket operators anywhere, same constraint as the rest of this
   header (see mission4_sample_signal): loop bounds use !=, comparisons use
   signbit on a subtraction.

   Returns FALSE and leaves DROP_POINT untouched if there are too few
   samples or the geometry is degenerate (all samples nearly collinear, so
   the ranges do not pin a point) - the caller then keeps the old
   best-sample estimate, which is poor but never absurd. */
static inline bool mission4_solve_source(uint8_t drop_wp)
{
  if (signbit((float)mission4_sample_count - 8.0f)) { return FALSE; }

  double s11 = 0.0, s12 = 0.0, s13 = 0.0, s22 = 0.0, s23 = 0.0, s33 = 0.0;
  double t1 = 0.0, t2 = 0.0, t3 = 0.0;
  uint16_t i;
  uint16_t n = mission4_sample_count;

  for (i = 0; i != n; i++) {
    double zi = (double)mission4_sample_z[i];
    double slant = (double)MISSION4_KTR_REF_DIST *
                   pow(10.0, ((double)MISSION4_KTR_REF_SPL - (double)mission4_sample_spl[i]) / 20.0);
    double h2 = slant * slant - zi * zi;
    /* Sample taken essentially overhead, or a range shorter than the
       aircraft's own altitude: no usable horizontal information. */
    if (signbit((float)h2)) { continue; }
    double xi = (double)mission4_sample_x[i];
    double yi = (double)mission4_sample_y[i];
    double r  = xi * xi + yi * yi - h2;
    double a1 = 2.0 * xi, a2 = 2.0 * yi, a3 = -1.0;
    s11 += a1 * a1; s12 += a1 * a2; s13 += a1 * a3;
    s22 += a2 * a2; s23 += a2 * a3; s33 += a3 * a3;
    t1  += a1 * r;  t2  += a2 * r;  t3  += a3 * r;
  }

  /* Symmetric 3x3 solve via the adjugate. */
  double A11 = s22 * s33 - s23 * s23;
  double A12 = s13 * s23 - s12 * s33;
  double A13 = s12 * s23 - s13 * s22;
  double A22 = s11 * s33 - s13 * s13;
  double A23 = s13 * s12 - s11 * s23;
  double det = s11 * A11 + s12 * A12 + s13 * A13;
  if (signbit((float)(fabs(det) - 1.0e-3))) { return FALSE; }

  double X = (A11 * t1 + A12 * t2 + A13 * t3) / det;
  double Y = (A12 * t1 + A22 * t2 + A23 * t3) / det;

  waypoints[drop_wp].x = (float)X;
  waypoints[drop_wp].y = (float)Y;
  return TRUE;
}

static inline bool mission4_peak_passed(void) {
  if (signbit((float)mission4_phase2_samples - (float)MISSION4_PEAK_MIN_SAMPLES)) {
    return false;
  }
  if (signbit((float)mission4_worse_streak - (float)MISSION4_PEAK_CONFIRM_COUNT)) {
    return false;
  }
  /* Side effect, same reason DROP_POINT moved into mission4_sample_signal()
     above: this return value drives a flight-plan exception, which
     deroutes immediately when true, skipping the rest of the calling
     block — so a sound_detected=TRUE stage placed after Phase2's go leg
     would almost never actually run, since firing early is this
     function's entire purpose. Setting it here instead means it's
     genuinely true the instant the search actually commits, regardless
     of which exit path (this exception, or the chord completing
     naturally) got there. */
  sound_detected = TRUE;
  return true;
}

static inline bool mission4_sample_signal(uint8_t source_wp, uint8_t drop_wp) {
  /* No raw angle-bracket comparison operators anywhere in this function
     on purpose, including greater-or-equal — gen_aircraft's flight-plan
     writer does not re-escape header text on output, so even a
     correctly-escaped entity in the source corrupts the per-aircraft
     generated flight_plan.xml downstream once it round-trips back out
     (confirmed earlier this session, see mission4_dist2_to_wp's comment
     above for the original finding). signbit() on a subtraction does
     the same comparisons without needing the operator characters at
     all. */
  if (!signbit(autopilot.flight_time - mission4_last_sample_time - MISSION4_SAMPLE_PERIOD)) {
    mission4_last_sample_time = autopilot.flight_time;
    /* True 3D distance (source assumed near ground level, so the
       aircraft's own altitude IS the vertical leg of this triangle) —
       this is the simulator's hidden ground truth, never exposed to the
       search logic directly, only through the spl value below. */
    float dx = GetPosX() - waypoints[source_wp].x;
    float dy = GetPosY() - waypoints[source_wp].y;
    float dz = GetPosAlt() - GetAltRef();
    float dist = sqrtf(dx * dx + dy * dy + dz * dz);
    float spl = MISSION4_KTR_REF_SPL - 20.0f * log10f(dist / MISSION4_KTR_REF_DIST);
    if (signbit((float)mission4_sample_count - (float)MISSION4_MAX_SAMPLES)) {
      mission4_sample_x[mission4_sample_count] = GetPosX();
      mission4_sample_y[mission4_sample_count] = GetPosY();
      mission4_sample_spl[mission4_sample_count] = spl;
      mission4_sample_z[mission4_sample_count] = GetPosAlt() - GetAltRef();
      mission4_sample_count++;
    }
    /* Altitude-compensated ranking: invert spl back into an implied
       slant range using the same calibration, then subtract the
       aircraft's own (precisely known) altitude to isolate the
       horizontal component — see the function-level comment above for
       why this matters here. Clamped at zero for the case an implied
       slant range comes out at or below the aircraft's own altitude
       (numerically odd but not impossible with a noisy real sensor;
       treated as "effectively directly overhead"). */
    float own_alt = GetPosAlt() - GetAltRef();
    float slant = MISSION4_KTR_REF_DIST * powf(10.0f, (MISSION4_KTR_REF_SPL - spl) / 20.0f);
    float horiz2 = slant * slant - own_alt * own_alt;
    if (signbit(horiz2)) {
      horiz2 = 0.0f;
    }
    float horiz = sqrtf(horiz2);
    if (signbit(horiz - mission4_best_horiz)) {
      mission4_best_horiz = horiz;
      mission4_best_x = GetPosX();
      mission4_best_y = GetPosY();
      /* DROP_POINT tracks the current best CONTINUOUSLY, right here,
         rather than only being finalized as a trailing stage after
         Phase2's go leg — confirmed via telemetry this matters: when
         mission4_peak_passed() below fires, it's an exception, and
         exceptions deroute immediately, skipping the rest of the block
         entirely (the same "exceptions run before stages" mechanism
         documented elsewhere in this file, just biting a different way
         here) — so a one-time finalization stage placed after the go leg
         almost never actually ran, since interrupting the leg early via
         peak_passed is the exception's entire purpose. DROP_POINT was
         found stuck at its own placeholder default (identical to
         SEARCH_CENTER's coordinates) after a real run for exactly this
         reason — never updated at all, not corrupted data. Writing it
         here instead means it's always current the instant a new best
         is found, regardless of which exit path the search eventually
         takes. waypoints[drop_wp] directly, not WaypointX(WP_DROP_POINT):
         the WP_* macros aren't defined until after this header's own
         functions in the generated flight_plan.h (confirmed by checking
         it directly), the same reason mission4_dist2_to_wp() above takes
         a waypoint index parameter instead of a hardcoded WP_ constant. */
      waypoints[drop_wp].x = mission4_best_x;
      waypoints[drop_wp].y = mission4_best_y;
    }
    /* Trend tracking for mission4_peak_passed() above: this sample vs.
       the immediately preceding one (not the best-ever), so this is
       "which way is it moving right now", independent of best-tracking. */
    if (!signbit(horiz - mission4_prev_horiz)) {
      mission4_worse_streak++;
    } else {
      mission4_worse_streak = 0;
    }
    mission4_prev_horiz = horiz;
    /* Counts every sample regardless of which block is active — reset to
       0 at the end of phase 1 (same place/reasoning as
       mission4_worse_streak's reset), so it only actually measures "how
       many samples into phase 2" by the time phase 2 can read it. */
    mission4_phase2_samples++;
  }
  return false;
}

/* Mission4 (Valkenburg): a single aircraft, so a short fixed launch delay -
   same helper name/shape as mission1_strasbourg.xml so the Holding point and
   Geo init blocks below are identical to that file's.
   No AC_ID special-casing anywhere in this plan, unlike mission4_strasbourg
   which gates on AC_ID 112 because Cadby shares that file. Here the gating
   would only be a trap: whichever aircraft is assigned this plan should fly
   it, and hardcoding one id means a different one silently falls through to
   Standby instead of starting the mission. */
static inline float mission1_geo_init_delay(void) {
  return 5;
}
static inline float mission1_holding_delay(void) {
  return 5;
}
